// Per-job non-custodial escrow with HTLC-style release keyed on the quorum
// result hash (BLOCKCHAIN_ECONOMICS §6.2, §13). The requester locks the max bid
// B at deploy; settlement is gated on presenting the agreed quorum hash and is
// bounded by B with any remainder refunded to the requester; on timeout the full
// escrow refunds. No platform key can ever take custody.
//
// SECURITY HARDENING (see escrow_types.tolk for the full trust model):
//   B1  the arbiter can only pay requester-pre-committed candidates (and never
//       itself) — a single compromised arbiter cannot redirect funds.
//   B2  every pushed payout is BOUNCEABLE; a bounced payout is credited to a
//       pull-ledger (`pending`) keyed by the recipient, never silently lost.
//   B3  winner/fee/participants are paid as fixed bounceable sends, then the
//       requester is refunded with RAWRESERVE + CARRY_ALL_BALANCE so storage-rent
//       erosion can never make the trailing refund underpay.
//   B4  the participants set is bounded so all payouts fit one action phase.

import "common"
import "escrow_types"

contract JobEscrow {
    storage: EscrowStorage
    incomingMessages: AllowedMessageToEscrow
}

type AllowedMessageToEscrow =
    | EscrowSettle
    | EscrowRefund
    | EscrowTopUp
    | EscrowClaim

// B2 bounce-safety: a pushed payout (winner / fee / participant / requester
// refund) that the recipient could not accept bounces back here. Credit the
// returned value to the pull-ledger keyed by the recipient (= the bounced-from
// address) so it is never lost; the recipient (or a keeper on their behalf) later
// pulls it with `EscrowClaim`. The amount is the bounced message value.
fun onBouncedMessage(in: InMessageBounced) {
    var body = in.bouncedBody;
    body.skipBouncedPrefix();
    val op = body.loadUint(32);
    if (op == OP_ESCROW_PAYOUT) {
        var storage = lazy EscrowStorage.load();
        val prev = storage.pending.get(in.senderAddress);
        val had: coins = prev.isFound ? prev.loadValue() : 0;
        storage.pending.set(in.senderAddress, had + in.valueCoins);
        storage.save();
    }
}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToEscrow.fromSlice(in.body);

    match (msg) {
        EscrowSettle => {
            var storage = lazy EscrowStorage.load();
            assert (in.senderAddress == storage.arbiter) throw ErrCode.NOT_ARBITER;
            assert (!storage.settled) throw ErrCode.ALREADY_SETTLED;

            val terms = storage.terms.load();
            // HTLC lock: funds only unlock for the agreed quorum result hash.
            assert (msg.resultHash == terms.expectedHash) throw ErrCode.HASH_MISMATCH;

            // B1: the candidate set must be EXACTLY what the requester pre-committed
            // to at open. This is what stops a compromised arbiter from naming an
            // arbitrary payee (e.g. itself) — every payee is checked for membership
            // below, and the set itself is requester-authorized.
            assert (candidatesCommitment(msg.candidates) == terms.candidatesHash) throw ErrCode.SETTLE_POLICY_MISMATCH;
            // B1 defense-in-depth: the arbiter can never be the winner.
            assert (msg.winner != storage.arbiter) throw ErrCode.NOT_OWNER_SIG;
            // B1: the winner must be a requester-authorized candidate.
            assert (msg.candidates.exists(msg.winner)) throw ErrCode.SETTLE_POLICY_MISMATCH;

            // Sum participation commissions, bound the count (B4), and verify each
            // participant is also a requester-authorized candidate (B1).
            var participantsTotal: coins = 0;
            var count = 0;
            var entry = msg.participants.findFirst();
            while (entry.isFound) {
                count += 1;
                assert (count <= MAX_SETTLE_PARTICIPANTS) throw ErrCode.TOO_MANY_PARTICIPANTS;
                val who = entry.getKey();
                assert (msg.candidates.exists(who)) throw ErrCode.SETTLE_POLICY_MISMATCH;
                participantsTotal += entry.loadValue();
                entry = msg.participants.iterateNext(entry);
            }

            val total = msg.winnerAmount + msg.platformFee + participantsTotal;
            assert (total <= storage.escrowAmount) throw ErrCode.PAYOUT_EXCEEDS_ESCROW;

            storage.settled = true;
            storage.save();

            // B3: keep a minimal storage buffer so the contract survives (and can
            // still receive bounces), then pay the fixed amounts and finally sweep
            // the TRUE remainder to the requester with CARRY_ALL_BALANCE — so rent
            // erosion can never make the requester's refund silently underpay.
            reserveToncoinsOnBalance(MIN_TONS_FOR_STORAGE, RESERVE_MODE_EXACT_AMOUNT);

            // Winner: base + perf bonus (bounceable; bounce → pull-ledger).
            if (msg.winnerAmount > 0) {
                payout(msg.winner, msg.winnerAmount, msg.queryId);
            }
            // Platform fee (treasury is from terms, never arbiter-chosen).
            if (msg.platformFee > 0) {
                payout(terms.treasury, msg.platformFee, msg.queryId);
            }
            // Fixed participation commission to each agreeing non-winner.
            var p = msg.participants.findFirst();
            while (p.isFound) {
                val who = p.getKey();
                val amt = p.loadValue();
                if (amt > 0) {
                    payout(who, amt, msg.queryId);
                }
                p = msg.participants.iterateNext(p);
            }
            // Refund the unspent escrow slack to the requester (§4.2) via
            // carry-remaining so the requester gets exactly what is left after the
            // fixed payouts + reserved buffer — never a stale computed slack.
            refundRemaining(storage.requester, msg.queryId);
        }

        // Refund-on-timeout: if the job is not settled by the deadline, anyone can
        // trigger a full refund to the requester (funds always go to the requester).
        EscrowRefund => {
            var storage = lazy EscrowStorage.load();
            assert (!storage.settled) throw ErrCode.ALREADY_SETTLED;
            assert (blockchain.now() >= storage.deadline) throw ErrCode.TIMEOUT_NOT_REACHED;

            storage.settled = true;
            storage.save();

            val refundMsg = createMessage({
                bounce: BounceMode.NoBounce,
                dest: storage.requester,
                value: 0,
            });
            refundMsg.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
        }

        // B2 pull path: deliver a queued/bounced payout to the recipient it is
        // keyed under. Anyone may trigger it (keeper-friendly), but the funds can
        // only go to that recipient — so it cannot be used to redirect a payout.
        EscrowClaim => {
            var storage = lazy EscrowStorage.load();
            val found = storage.pending.get(msg.recipient);
            assert (found.isFound) throw ErrCode.PAYOUT_EXCEEDS_ESCROW;
            val amount = found.loadValue();
            assert (amount > 0) throw ErrCode.PAYOUT_EXCEEDS_ESCROW;
            storage.pending.delete(msg.recipient);
            storage.save();
            // Re-deliver bounceable; if it bounces again it is re-credited.
            payout(msg.recipient, amount, msg.queryId);
        }

        EscrowTopUp => {
            // accept additional funding / storage rent
        }

        else => {
            assert (in.body.isEmpty()) throw ErrCode.INVALID_OP;
        }
    }
}

// B2/B3: a single fixed-value payout, BOUNCEABLE with an op-tagged body so a
// failed delivery returns the funds here and `onBouncedMessage` can credit the
// pull-ledger. PAY_FEES_SEPARATELY so the recipient receives EXACTLY `amount`.
// NOT IGNORE_ERRORS: we want a real bounce (recoverable), not a silent drop.
fun payout(to: address, amount: coins, queryId: int) {
    val m = createMessage({
        bounce: BounceMode.Only256BitsOfBody,
        dest: to,
        value: amount,
        body: EscrowPayout { queryId: queryId as uint64 },
    });
    m.send(SEND_MODE_PAY_FEES_SEPARATELY);
}

// B3: refund the requester with carry-remaining semantics — sends whatever
// balance is left after the fixed payouts and the reserved storage buffer. Made
// bounceable so a failed refund is credited to the pull-ledger rather than lost.
fun refundRemaining(to: address, queryId: int) {
    val m = createMessage({
        bounce: BounceMode.Only256BitsOfBody,
        dest: to,
        value: 0,
        body: EscrowPayout { queryId: queryId as uint64 },
    });
    m.send(SEND_MODE_CARRY_ALL_BALANCE);
}

// ---------------------------------------------------------------------------
// Getters
// ---------------------------------------------------------------------------

get fun get_escrow_state(): EscrowState {
    val storage = lazy EscrowStorage.load();
    return {
        escrowAmount: storage.escrowAmount,
        deadline: storage.deadline,
        settled: storage.settled,
        paramsVersion: storage.terms.load().paramsVersion,
    };
}

// The GlobalParams version this job was opened under (bound into terms), so
// settlement / dispute resolution references the exact params in force.
get fun get_params_version(): int {
    val storage = lazy EscrowStorage.load();
    return storage.terms.load().paramsVersion;
}

get fun get_requester(): address {
    val storage = lazy EscrowStorage.load();
    return storage.requester;
}

get fun get_expected_hash(): int {
    val storage = lazy EscrowStorage.load();
    return storage.terms.load().expectedHash;
}

// B1: the requester's pre-committed candidate-set commitment (so the off-chain
// coordinator/bridge can confirm the escrow binds the candidate set it expects).
get fun get_candidates_hash(): int {
    val storage = lazy EscrowStorage.load();
    return storage.terms.load().candidatesHash;
}

// B2: the queued/bounced pull-balance for a recipient (0 if none). Lets a
// recipient/keeper see what is claimable via `EscrowClaim`.
get fun get_pending(recipient: address): int {
    val storage = lazy EscrowStorage.load();
    val found = storage.pending.get(recipient);
    if (!found.isFound) {
        return 0;
    }
    return found.loadValue();
}

// Shared error codes, opcodes and constants for the duckdb-p2p settlement layer.
//
// These contracts implement the *paid* path of the economic layer described in
// `docs/BLOCKCHAIN_ECONOMICS.md`. Free jobs never touch any of this code — the
// requester runs them through the off-chain coordinator with the `NoopSettlement`
// path and there is zero on-chain interaction (see §8.2 "Free vs paid path").
//
// Design constraints honoured here (BLOCKCHAIN_ECONOMICS §1, §8):
//   * sharded per-node state (no global contract): one StakeVault per node,
//     one JobEscrow per job — never a single hot contract.
//   * non-custodial: release is governed entirely by contract code (quorum
//     result-hash, challenge window, unbonding cooldown), never a platform key.
//   * defensive TON style: explicit gas floors, bounce-safe, carry-value.
// ---------------------------------------------------------------------------
// Error codes — a typed `enum` (Tolk production guidance) instead of loose
// `const`s, so every `throw`/`assert` is checked against a single named set and
// a typo can't silently invent a new code. The backing type is `int32` (the TVM
// exit-code width); the numeric values are FROZEN — they are the contract ABI
// that off-chain code and tests assert against — so they are kept verbatim.
// Reference members as `ErrCode.NOT_OWNER`, etc.
// ---------------------------------------------------------------------------

enum ErrCode: int32 {
    // Jetton / receipt wallet
    NOT_OWNER = 132            // sender is not the contract owner
    NOT_FROM_MASTER = 133      // sender is not the jetton master (vault)
    NOT_VALID_WALLET = 134     // sender is not a legitimate sibling receipt wallet
    UNAUTHORIZED_BURN = 135    // burn notification not from the owner's wallet
    BALANCE_NEGATIVE = 136     // resulting balance would be negative
    NOT_ENOUGH_GAS = 137       // attached value too small to cover the operation
    RECEIPT_LOCKED = 138       // stake-receipt jetton is non-transferable (anti-exit)
    INVALID_OP = 0xffff        // unknown opcode

    // Stake vault
    NOT_SLASHER = 200          // sender is not the authorized slasher (dispute contract)
    NOTHING_TO_UNBOND = 201    // unbond requested but no eligible stake
    UNBOND_IN_PROGRESS = 202   // a prior unbond is still cooling down
    COOLDOWN_NOT_ELAPSED = 203 // withdraw before the unbonding cooldown finished
    NO_UNBONDING = 204         // withdraw with nothing in the unbonding bucket
    KEEPER_TOO_EARLY = 205     // keeper withdraw before the owner-grace window
    SLASH_EXCEEDS_STAKE = 206  // slash amount larger than slashable stake
    INVALID_SPLIT = 207        // slash split bps do not sum to 10000
    // Timelocked governance code upgrade (§8.6) — preserves the non-custodial
    // guarantee: an announced code swap can only be APPLIED after a delay >= the
    // unbonding window, so stakers can exit before any new code takes effect.
    NO_PENDING_UPGRADE = 208   // apply/cancel with nothing announced
    UPGRADE_TIMELOCK_ACTIVE = 209 // apply before the timelock delay elapsed
    UPGRADE_CODE_MISMATCH = 210 // applied code != the announced (hash-committed) code

    // Escrow
    ESCROW_NOT_FUNDED = 220    // escrow opened without the requester's max-bid B
    NOT_REQUESTER = 221        // settle/refund by someone other than the requester
    NOT_ARBITER = 222          // settle by someone other than the bound arbiter
    HASH_MISMATCH = 223        // provided result hash != the committed quorum hash
    ALREADY_SETTLED = 224      // escrow already released
    TIMEOUT_NOT_REACHED = 225  // refund-on-timeout before the deadline
    PAYOUT_EXCEEDS_ESCROW = 226 // requested payout exceeds the locked escrow B

    // Record anchor / dispute
    BAD_PREV_ROOT = 240        // submitted root does not chain to the stored prev_root
    EPOCH_REGRESSION = 241     // epoch did not advance monotonically
    INSUFFICIENT_ANCHOR_STAKE = 242 // keeper stake-weight below the acceptance threshold
    BAD_INCLUSION_PROOF = 243  // Merkle inclusion proof does not reproduce the root
    DISPUTE_BOND_TOO_LOW = 244 // challenger bond below the configured minimum
    NO_SUCH_DISPUTE = 245      // verdict for an unknown dispute id
    NOT_VERDICT_AUTHORITY = 246 // verdict from a non-authoritative source
    // --- Appended (security hardening; never renumber the frozen codes above) ---
    DISPUTE_NOT_OPEN = 247     // resolve a dispute that is not in the open (0) state (double-resolve)
    UNKNOWN_EPOCH = 248        // dispute references an epoch that was never anchored
    PROOF_TOO_DEEP = 249       // Merkle proof exceeds the max depth bound (gas-griefing guard)
    NOT_ANCHOR_KEEPER = 250    // root submitted by an address that is not the authorized keeper
    ZERO_ROOT = 251            // refuse anchoring an empty / all-zero root
    BOND_FLOOR_TOO_LOW = 252   // configured disputeBondMin is below the on-chain floor (> 0)

    // Global params (platform-wide config)
    NOT_ADMIN = 260            // sender is not the configured admin (or multisig)
    PARAMS_OUT_OF_BOUNDS = 261 // proposed params violate a §12 invariant

    // --- Appended: escrow / vault payout-authorization + bounce hardening ------
    NOT_OWNER_SIG = 280        // settle split not authorized by the fund-owner (requester) commitment
    SETTLE_POLICY_MISMATCH = 281 // settle payload does not match the requester's pre-committed policy hash
    TOO_MANY_PARTICIPANTS = 282  // participants map exceeds the on-chain payout bound (action/gas safety)
    UPGRADE_NOT_AUTHORITY = 283  // upgrade announced/applied by a non-upgrade-authority (separated from slasher)
    BAD_BOUNTY_BPS = 284         // keeperBountyBps out of [0, BPS_DENOM] (config sanity)
}

// ---------------------------------------------------------------------------
// Opcodes — keep TEP-74 standard values verbatim for ecosystem interop.
// ---------------------------------------------------------------------------

// TEP-74 jetton standard
const OP_JETTON_TRANSFER = 0x0f8a7ea5
const OP_JETTON_TRANSFER_INTERNAL = 0x178d4519
const OP_JETTON_NOTIFICATION = 0x7362d09c
const OP_JETTON_EXCESSES = 0xd53276db
const OP_JETTON_BURN = 0x595f07bc
const OP_JETTON_BURN_NOTIFICATION = 0x7bdd97de
const OP_PROVIDE_WALLET_ADDRESS = 0x2c76b973
const OP_TAKE_WALLET_ADDRESS = 0xd1735400

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MIN_TONS_FOR_STORAGE = ton("0.05")
const BPS_DENOM = 10000 // basis-points denominator for splits/fractions

// Status bit flags for the stake-receipt wallet.
const RECEIPT_STATUS_LOCKED = 1 // bit 0: outgoing transfers locked (default)

// Max Merkle inclusion-proof depth the on-chain verifier will walk before
// aborting (A4: an attacker-supplied proof chain is otherwise unbounded → gas
// griefing). 32 levels = up to 2^32 leaves per epoch, far beyond any realistic
// epoch batch, so this never rejects an honest proof.
const MAX_MERKLE_PROOF_DEPTH = 32

// On-chain floor for the dispute bond minimum (A5): a config that sets
// disputeBondMin below this is rejected at deploy/validate time so near-zero-bond
// griefing is impossible. 0.01 TON is a token but non-trivial anti-spam cost.
const MIN_DISPUTE_BOND_FLOOR = ton("0.01")

// Upper bound on the number of agreeing non-winners paid in a single settle
// action phase (B4): bounding the participants map keeps the settle within the
// TVM action/gas limit so a payout can never be partial. 32 covers the realistic
// committee size (N_max=10) with wide headroom.
const MAX_SETTLE_PARTICIPANTS = 32

// Storage + messages for the per-job escrow / HTLC settlement contract.
// See BLOCKCHAIN_ECONOMICS §4 (earning function), §6.2 (who gets paid), and the
// "HTLC-style escrow release keyed on the quorum result-hash" recommendation
// in §13. Non-custodial: the arbiter can only DIRECT payouts bounded by the
// locked escrow B and gated on the agreed result hash; it can never seize funds,
// and any leftover always refunds to the requester.
//
// Touched by PAID jobs only. Free jobs never open an escrow (§8.2).
//
// TRUST MODEL (B1) — a single compromised arbiter CANNOT redirect funds to
// itself. The requester PRE-COMMITS, at escrow-open time, to the exact set of
// payout-eligible candidates (the N workers it dispatched) via
// `EscrowTerms.candidatesHash`. The arbiter, at settle, only chooses WHICH of
// those requester-authorized candidates wins and the split — it can never name an
// arbitrary recipient (e.g. itself), because every payee (winner + each
// participant) is checked for membership in the committed set, and the arbiter is
// additionally barred from being the winner. So the arbiter supplies the quorum
// VERDICT (result hash + ranking within the committed set), while the fund-owner
// (requester) authorizes the RECIPIENT SET — neither party alone can move funds
// to an outside address.

import "common"

const OP_ESCROW_SETTLE = 0x4553_4302
const OP_ESCROW_REFUND = 0x4553_4303
const OP_ESCROW_TOPUP = 0x4553_4300
const OP_ESCROW_CLAIM = 0x4553_4304  // pull a bounced/queued payout (B2 bounce-safety)
const OP_ESCROW_PAYOUT = 0x4553_4305 // outgoing payout op tag (carried so bounces are identifiable)

struct EscrowTerms {
    treasury: address     // platform-fee recipient
    expectedHash: uint256 // HTLC lock: settle must present this quorum result hash
    // B1: the requester's pre-committed authorization of the payout-eligible
    // candidate set. Computed off-chain as `hash(candidates dict cell)` over the
    // `map<address, uint1>` of the N dispatched workers' payout wallets
    // (`beginCell().storeDict(candidates).endCell().hash()`), and bound into the
    // escrow's terms (hence its deterministic address) at open. At settle, the
    // arbiter must present a candidate set that hashes to exactly this value, and
    // every payee must be a member — so the arbiter cannot pay an outside address.
    candidatesHash: uint256
    // GlobalParams version/seqno in force when this job was opened. Bound into
    // the escrow's terms (hence its deterministic address) so the host,
    // requester and coordinator all agree which ecosystem params governed the
    // job at settlement / dispute time. Appended last → additive layout.
    paramsVersion: uint32
}

struct EscrowStorage {
    requester: address  // who funded B and receives refunds
    arbiter: address    // quorum oracle / coordinator authorized to settle
    escrowAmount: coins // B — the requester's max bid, locked up front
    deadline: uint32    // refund-on-timeout deadline (unix secs)
    settled: bool
    terms: Cell<EscrowTerms>
    // B2 bounce-safety: a pull-withdrawal ledger. If a pushed payout (winner /
    // fee / participant / refund) BOUNCES because the recipient could not accept
    // it, `onBouncedMessage` credits the returned amount here (keyed by the
    // recipient = the bounced-from address) instead of letting it vanish. The
    // recipient (or anyone, on their behalf) later pulls it with `EscrowClaim`.
    // This converts the fragile fire-and-forget sends into a recoverable
    // push-then-pull pattern. Appended last → additive layout.
    pending: map<address, coins>
}

fun EscrowStorage.load(): EscrowStorage {
    return EscrowStorage.fromCell(contract.getData());
}

fun EscrowStorage.save(self) {
    contract.setData(self.toCell());
}

// Settle after the quorum verdict. `participants` maps each agreeing non-winner
// to its fixed participation commission (§6.2). `winnerAmount` is base + perf
// bonus. Any escrow not paid out refunds to the requester.
//
// B1: `candidates` is the requester-committed payout-eligible set. It MUST hash
// to `terms.candidatesHash`; the `winner` and every `participants` key MUST be a
// member; and `winner` MUST NOT be the arbiter. B4: `participants` is bounded to
// MAX_SETTLE_PARTICIPANTS so all payouts fit one action phase.
struct (0x4553_4302) EscrowSettle {
    queryId: uint64
    resultHash: uint256 // the agreed quorum hash — must equal terms.expectedHash
    winner: address
    winnerAmount: coins
    platformFee: coins
    participants: map<address, coins>
    candidates: map<address, uint1> // requester-committed eligible set (hashed-checked)
}

struct (0x4553_4303) EscrowRefund {
    queryId: uint64
}

struct (0x4553_4300) EscrowTopUp {
    queryId: uint64
}

// Pull a queued/bounced payout (B2). Anyone may trigger it; funds always go to
// the `recipient` that the credit is keyed under (so a stuck winner's payout can
// be re-delivered by a keeper without letting anyone redirect it).
struct (0x4553_4304) EscrowClaim {
    queryId: uint64
    recipient: address
}

// Outgoing payout body tag (B2). Carried on every pushed payout so a bounce is
// recognizable; the recipient is recovered from the bounce's sender address, the
// amount from the bounce's value — so the body only needs the op tag + queryId.
struct (0x4553_4305) EscrowPayout {
    queryId: uint64
}

struct EscrowState {
    escrowAmount: coins
    deadline: uint32
    settled: bool
    paramsVersion: uint32
}

// B1 helpers ----------------------------------------------------------------

// Canonical commitment over the requester-authorized candidate set: the repr
// hash of a cell holding the `map<address, uint1>`. TON dicts are key-sorted, so
// this is order-independent and the off-chain Rust builder reproduces it byte for
// byte (`beginCell().storeDict(candidates).endCell().hash()`).
fun candidatesCommitment(candidates: map<address, uint1>): int {
    return beginCell().storeDict(candidates.toLowLevelDict()).endCell().hash();
}
